    #include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct
{
    int *arr;     // dynamic array to store stack elements
    int top;      // index of top element
    int capacity; // current capacity of the stack
} Stack;

// Initialize stack
Stack *createStack(int initialCapacity)
{
    Stack *stack = (Stack *)malloc(sizeof(Stack));
    stack->arr = (int *)malloc(initialCapacity * sizeof(int));
    stack->top = -1;
    stack->capacity = initialCapacity;
    return stack;
}

// Push operation
void push(Stack *stack, int value)
{
    // Resize array if needed
    if (stack->top + 1 >= stack->capacity)
    {
        stack->capacity *= 2; // double the capacity
        stack->arr = (int *)realloc(stack->arr, stack->capacity * sizeof(int));
    }
    stack->arr[++stack->top] = value;
}

// Pop operation
int pop(Stack *stack)
{
    if (stack->top == -1)
    {
        printf("Stack Underflow\n");
        return -1;
    }
    return stack->arr[stack->top--];
}

// Peek operation
int peek(Stack *stack)
{
    if (stack->top == -1)
    {
        printf("Stack is Empty\n");
        return -1;
    }
    return stack->arr[stack->top];
}

// Check if stack is empty
bool isEmpty(Stack *stack)
{
    return stack->top == -1;
}

// Current size of stack
int size(Stack *stack)
{
    return stack->top + 1;
}

// Free stack memory
void freeStack(Stack *stack)
{
    free(stack->arr);
    free(stack);
}

int main()
{
    Stack *st = createStack(2); // initial capacity 2

    // Push elements
    push(st, 1);
    push(st, 2);
    push(st, 3);
    push(st, 4);

    // Pop one element
    printf("Popped: %d\n", pop(st));

    // Peek top element
    printf("Top element: %d\n", peek(st));

    // Check if stack is empty
    printf("Is stack empty: %s\n", isEmpty(st) ? "Yes" : "No");

    // Current size
    printf("Current size: %d\n", size(st));

    freeStack(st); // free memory
    return 0;
}


